// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkProgramEvidenceNeed) predicate.WorkProgramEvidenceNeed {
	return predicate.WorkProgramEvidenceNeed(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkProgramEvidenceNeed) predicate.WorkProgramEvidenceNeed {
	return predicate.WorkProgramEvidenceNeed(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkProgramEvidenceNeed) predicate.WorkProgramEvidenceNeed {
	return predicate.WorkProgramEvidenceNeed(sql.NotPredicates(p))
}
